INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (1, N'Zahav', 12, N'A Society Hill landmark for modern Israeli cooking. Dinner starts with silky hummus, a spread of salatim and laffa bread from the wood-fired oven, and the pomegranate-glazed lamb shoulder is built for sharing.', N'237 St James Pl', N'Philadelphia', N'PA', N'19106', N'(215) 625-8800', N'', N'Michael Solomonov & Steve Cook', N'https://www.zahavrestaurant.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/zahav.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/middleeastern.jpg', '2026-01-01T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (2, N'Vetri Cucina', 9, N'An intimate townhouse dining room serving a multi-course Italian tasting menu. Handmade pastas like spinach gnocchi and almond tortellini have made it one of the city''s special-occasion favorites.', N'1312 Spruce St', N'Philadelphia', N'PA', N'19107', N'(215) 732-3478', N'', N'Marc Vetri', N'https://vetricucina.com', 4, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/vetricucina.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/italian.jpg', '2026-01-06T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (3, N'Pat''s King of Steaks', 2, N'The South Philly corner stand that claims to have invented the cheesesteak in 1930. Order at the window, say "wit" or "witout" for onions, and eat at the outdoor counters any hour of the day.', N'1237 E Passyunk Ave', N'Philadelphia', N'PA', N'19147', N'(215) 468-1546', N'', N'Frank Olivieri', N'https://www.patskingofsteaks.com', 1, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/patskingofsteaks.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/cheesesteaks.jpg', '2026-01-11T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (4, N'Geno''s Steaks', 2, N'Pat''s neon-lit rival across the intersection at 9th and Passyunk. Thin-sliced ribeye on a fresh roll, served around the clock since 1966.', N'1219 S 9th St', N'Philadelphia', N'PA', N'19147', N'(215) 389-0659', N'', N'Geno Vento', N'https://www.genosteaks.com', 1, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/genossteaks.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/cheesesteaks.jpg', '2026-01-16T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (5, N'Dalessandro''s Steaks', 2, N'A Roxborough neighborhood shop where the beef is chopped fine on the griddle and piled high. Locals swear by it, so expect a line at lunch and grab a seat at the counter if you can.', N'600 Wendover St', N'Philadelphia', N'PA', N'19128', N'(215) 482-5407', N'', N'', N'https://dalessandros.com', 1, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/dalessandrossteaks.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/cheesesteaks.jpg', '2026-01-21T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (6, N'Parc', 6, N'A bustling Parisian-style brasserie on Rittenhouse Square with sidewalk tables, warm baskets of bread and classic bistro dishes from breakfast through late dinner.', N'227 S 18th St', N'Philadelphia', N'PA', N'19103', N'(215) 545-2262', N'', N'Stephen Starr', N'https://parc-restaurant.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/parc.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/french.jpg', '2026-02-01T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (7, N'Barbuzzo', 9, N'A lively Midtown Village wine bar with Mediterranean small plates, wood-fired pizzas and the famous salted caramel budino.', N'110 S 13th St', N'Philadelphia', N'PA', N'19107', N'(215) 546-9300', N'', N'Marcie Turney & Valerie Safran', N'https://www.barbuzzo.com', 2, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/barbuzzo.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/italian.jpg', '2026-02-06T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (8, N'Dim Sum Garden', 3, N'A Chinatown favorite for Shanghai-style soup dumplings. Bite a small hole, sip the broth, then try the pan-fried noodles and scallion pancakes.', N'1020 Race St', N'Philadelphia', N'PA', N'19107', N'(215) 873-0258', N'', N'', N'https://www.dimsumgardenphilly.com', 1, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/dimsumgarden.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/chinese.jpg', '2026-02-11T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (9, N'South Philly Barbacoa', 11, N'Chef Cristina Martinez''s Italian Market taqueria, known for slow-cooked lamb barbacoa served in fresh tortillas with consomme on the side.', N'1140 S 9th St', N'Philadelphia', N'PA', N'19147', N'(215) 694-3797', N'', N'Cristina Martinez & Ben Miller', N'https://chefcristinamartinez.com', 1, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/southphillybarbacoa.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/mexican.jpg', '2026-02-16T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (10, N'Suraya', 12, N'A Lebanese restaurant, market and garden in Fishtown. Fresh-baked man''oushe, colorful mezze and grilled kebabs come out of an open kitchen into a beautiful courtyard.', N'1528 Frankford Ave', N'Philadelphia', N'PA', N'19125', N'(215) 302-1900', N'', N'', N'https://www.surayaphilly.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/suraya.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/middleeastern.jpg', '2026-02-21T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (11, N'Kalaya', 16, N'Chef Nok Suntaranon''s Southern Thai restaurant in a soaring, plant-filled Fishtown dining room. Curries are bold and spicy, and dishes are made for passing around the table.', N'4 W Palmer St', N'Philadelphia', N'PA', N'19125', N'(215) 545-2535', N'', N'Chutatip "Nok" Suntaranon', N'https://kalayaphilly.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/kalaya.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/thai.jpg', '2026-03-01T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (12, N'Laser Wolf', 12, N'An Israeli-style skewer house in Kensington. Choose a grilled skewer and the table fills up with salatim, hummus and pita, with soft-serve to finish.', N'1301 N Howard St', N'Philadelphia', N'PA', N'19122', N'(267) 499-4660', N'', N'Michael Solomonov & Steve Cook', N'https://www.laserwolfphilly.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/laserwolf.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/middleeastern.jpg', '2026-03-06T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (13, N'Vernick Food & Drink', 1, N'Chef Greg Vernick''s Rittenhouse townhouse restaurant, where seasonal toasts, raw bar plates and wood-roasted dishes are served at a warm, buzzy bar and dining room.', N'2031 Walnut St', N'Philadelphia', N'PA', N'19103', N'(267) 639-6644', N'', N'Greg Vernick', N'https://www.vernickphilly.com', 4, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/vernickfoodanddrink.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/american.jpg', '2026-03-11T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (14, N'Estia', 7, N'A Mediterranean taverna on the Avenue of the Arts known for whole fish grilled over charcoal and sold by the pound, with live music on weekend nights.', N'1405 Locust St', N'Philadelphia', N'PA', N'19102', N'(215) 735-7700', N'', N'', N'https://www.estiarestaurant.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/estia.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/greek.jpg', '2026-03-16T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (15, N'Oyster House', 14, N'A family-run Center City raw bar with a long marble counter, a wall of vintage oyster plates and a daily list of East Coast oysters.', N'1516 Sansom St', N'Philadelphia', N'PA', N'19102', N'(215) 567-7683', N'', N'Sam Mink', N'https://oysterhousephilly.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/oysterhouse.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/seafood.jpg', '2026-03-21T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (16, N'Vietnam Restaurant', 17, N'A Chinatown favorite run by the Lai family since 1984, serving a dozen kinds of pho, grilled-meat vermicelli bowls and crispy spring rolls in a cozy two-floor dining room.', N'221 N 11th St', N'Philadelphia', N'PA', N'19107', N'(215) 592-1163', N'', N'The Lai family', N'https://eatatvietnam.com', 2, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/vietnamrestaurant.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/vietnamese.jpg', '2026-04-01T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (17, N'Morimoto', 10, N'Iron Chef Masaharu Morimoto''s sleek Old City dining room with a glowing, color-changing interior, creative sushi and a signature omakase.', N'723 Chestnut St', N'Philadelphia', N'PA', N'19106', N'(215) 413-9070', N'', N'Stephen Starr', N'https://morimotorestaurant.com', 4, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/morimoto.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/japanese.jpg', '2026-04-06T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (18, N'Amma''s South Indian Cuisine', 8, N'A Center City spot for South Indian specialties, from paper-thin dosas and fluffy idli to fragrant biryani and Chettinad curries.', N'1500 Walnut St', N'Philadelphia', N'PA', N'19102', N'(808) 762-6627', N'', N'', N'https://ammasrestaurants.com', 2, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/ammassouthindiancuisine.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/indian.jpg', '2026-04-11T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (19, N'Katz''s Delicatessen', 4, N'A Lower East Side deli serving hand-carved pastrami since 1888. Hold on to your ticket, tip the cutter and get ready for a sandwich stacked a mile high.', N'205 E Houston St', N'New York', N'NY', N'10002', N'(212) 254-2246', N'', N'Jake Dell', N'https://katzsdelicatessen.com', 2, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/katzsdelicatessen.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/delisandwiches.jpg', '2026-04-16T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (20, N'Peter Luger Steak House', 15, N'A Williamsburg steakhouse open since 1887, famous for dry-aged porterhouse for two, thick-cut bacon and old-school waiters.', N'178 Broadway', N'Brooklyn', N'NY', N'11211', N'(718) 387-7400', N'', N'', N'https://peterluger.com', 4, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/peterlugersteakhouse.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/steakhouse.jpg', '2026-04-21T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (21, N'Joe''s Pizza', 13, N'A Greenwich Village slice counter serving classic thin, foldable New York slices since 1975. Grab a plain slice and eat it on the sidewalk.', N'7 Carmine St', N'New York', N'NY', N'10014', N'(212) 366-1182', N'', N'', N'https://www.joespizzanyc.com', 1, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/joespizza.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/pizza.jpg', '2026-05-01T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (22, N'Lombardi''s', 13, N'Known as America''s first pizzeria, this Nolita spot bakes whole pies in a coal oven. Cash only and well worth the wait.', N'32 Spring St', N'New York', N'NY', N'10012', N'(212) 941-7994', N'', N'', N'https://www.firstpizza.com', 2, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/lombardis.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/pizza.jpg', '2026-05-06T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (23, N'Le Bernardin', 6, N'Chef Eric Ripert''s elegant Midtown temple to seafood, where nearly raw and lightly cooked fish are served with refined French sauces.', N'155 W 51st St', N'New York', N'NY', N'10019', N'(212) 554-1515', N'', N'Maguy Le Coze & Eric Ripert', N'https://www.le-bernardin.com', 4, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/lebernardin.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/french.jpg', '2026-05-11T00:00:00.000', NULL);
INSERT INTO [dbo].[Restaurants] ([RestaurantID], [RestaurantName], [CuisineID], [Description], [StreetAddress], [City], [State], [ZipCode], [Phone], [Email], [OwnerName], [WebsiteURL], [PriceRange], [LogoImagePath], [CoverImagePath], [DateAdded], [RepresentativeUserID]) VALUES (24, N'Balthazar', 6, N'A grand SoHo brasserie with red banquettes, antique mirrors and towering seafood platters, open from breakfast until late.', N'80 Spring St', N'New York', N'NY', N'10012', N'(212) 965-1414', N'', N'Keith McNally', N'https://balthazarny.com', 3, N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Logos/balthazar.png', N'https://raw.githubusercontent.com/HecatesRevenge/What-The-Fork-Images/main/Covers/french.jpg', '2026-05-16T00:00:00.000', NULL);
